259	mod tests {
260	    use super::*;
261	
262	    fn collect(store: &Buckets<i32, i32>) -> Vec<(i32, i32)> {
263	        store.iter().map(|(k, v)| (*k, *v)).collect()
264	    }
265	
266	    /// Re-checks both structural invariants the search relies on.
267	    fn assert_invariants(store: &Buckets<i32, i32>) {
268	        let mut total = 0;
269	        let mut previous: Option<i32> = None;
270	        for bucket in &store.buckets {
271	            assert!(!bucket.is_empty(), "empty bucket");
272	            for entry in bucket {
273	                if let Some(last) = previous {
274	                    assert!(last < entry.0, "keys out of order: {} then {}", last, entry.0);
275	                }
276	                previous = Some(entry.0);
277	            }
278	            total += bucket.len();
279	        }
280	        assert_eq!(total, store.len());
281	    }
282	
283	    #[test]
284	    fn ascending_inserts_split_and_stay_ordered() {
285	        let mut store = Buckets::new(4);
286	        for key in 0..200 {
287	            assert_eq!(store.insert(key, key * 10), None);
288	        }
289	        assert_invariants(&store);
290	        assert_eq!(collect(&store), (0..200).map(|k| (k, k * 10)).collect::<Vec<_>>());
291	    }
292	
293	    #[test]
294	    fn descending_inserts_stay_ordered() {
295	        let mut store = Buckets::new(4);
296	        for key in (0..200).rev() {
297	            store.insert(key, key * 10);
298	        }
299	        assert_invariants(&store);
300	        assert_eq!(collect(&store), (0..200).map(|k| (k, k * 10)).collect::<Vec<_>>());
301	    }
302	
303	    #[test]
304	    fn insert_replaces_and_reports_the_old_value() {
305	        let mut store = Buckets::new(4);
306	        store.insert(1, 100);
307	        assert_eq!(store.insert(1, 200), Some(100));
308	        assert_eq!(store.len(), 1);
309	        assert_eq!(store.get(&1), Some(&200));
310	    }
311	
312	    #[test]
313	    fn bounds_agree_with_a_linear_scan() {
314	        let mut store = Buckets::new(3);
315	        // Even keys only, so every odd probe falls between two entries.
316	        for key in 0..100 {
317	            store.insert(key * 2, key);
318	        }
319	        let keys: Vec<i32> = (0..100).map(|k| k * 2).collect();
320	        for probe in -3..205 {
321	            let lower = store.lower_bound(&probe);
322	            let expected_lower = keys.iter().position(|k| *k >= probe);
323	            assert_eq!(store.at(lower).map(|(k, _)| *k), expected_lower.map(|i| keys[i]));
324	            assert_eq!(lower == store.end(), expected_lower.is_none());
325	
326	            let upper = store.upper_bound(&probe);
327	            let expected_upper = keys.iter().position(|k| *k > probe);
328	            assert_eq!(store.at(upper).map(|(k, _)| *k), expected_upper.map(|i| keys[i]));
329	            assert_eq!(upper == store.end(), expected_upper.is_none());
330	
331	            let found = store.find(&probe);
332	            assert_eq!(found != store.end(), keys.contains(&probe));
333	        }
334	    }
335	
336	    #[test]
337	    fn advance_walks_every_entry_exactly_once() {
338	        let mut store = Buckets::new(3);
339	        for key in 0..50 {
340	            store.insert(key, key);
341	        }
342	        let mut pos = store.lower_bound(&i32::MIN);
343	        let mut walked = Vec::new();
344	        while pos != store.end() {
345	            walked.push(*store.at(pos).unwrap().0);
346	            pos = store.advance(pos);
347	        }
348	        assert_eq!(walked, (0..50).collect::<Vec<_>>());
349	        // Advancing past the end is saturating, never a panic.
350	        assert_eq!(store.advance(store.end()), store.end());
351	    }
352	
353	    #[test]
354	    fn removal_keeps_invariants_and_empties_cleanly() {
355	        let mut store = Buckets::new(4);
356	        for key in 0..200 {
357	            store.insert(key, key);
358	        }
359	        for key in (0..200).step_by(3) {
360	            assert_eq!(store.remove(&key), Some(key));
361	            assert_invariants(&store);
362	        }
363	        assert_eq!(store.remove(&0), None);
364	        let survivors: Vec<i32> = (0..200).filter(|k| k % 3 != 0).collect();
365	        assert_eq!(collect(&store).into_iter().map(|(k, _)| k).collect::<Vec<_>>(), survivors);
366	
367	        for key in survivors {
368	            store.remove(&key);
369	            assert_invariants(&store);
370	        }
371	        assert!(store.is_empty());
372	        assert_eq!(store.end(), Pos { bucket: 0, offset: 0 });
373	        assert_eq!(store.lower_bound(&7), store.end());
374	    }
375	
376	    #[test]
377	    fn get_or_insert_with_materialises_missing_keys() {
378	        let mut store = Buckets::new(2);
379	        for key in [5, 1, 9, 3] {
380	            store.insert(key, key);
381	        }
382	        assert_eq!(*store.get_or_insert_with(7, || -1), -1);
383	        assert_eq!(store.len(), 5);
384	        *store.get_or_insert_with(7, || -99) = 42;
385	        assert_eq!(store.len(), 5);
386	        assert_eq!(store.get(&7), Some(&42));
387	        assert_invariants(&store);
388	    }
