390	    /// The bucket layout must never be observable: it has to behave exactly like a
391	    /// sorted association list under an arbitrary mix of operations.
392	    #[test]
393	    fn matches_a_naive_model_under_random_operations() {
394	        let mut state = 0x2545_F491_4F6C_DD1Du64;
395	        let mut next = move || {
396	            state ^= state << 13;
397	            state ^= state >> 7;
398	            state ^= state << 17;
399	            state
400	        };
401	        for load in [1, 2, 3, 8, 64] {
402	            let mut store = Buckets::new(load);
403	            let mut model: Vec<(i32, i32)> = Vec::new();
404	            for step in 0..4000 {
405	                let key = (next() % 150) as i32;
406	                let slot = model.binary_search_by(|entry| entry.0.cmp(&key));
407	                if next() % 3 == 0 {
408	                    let removed = store.remove(&key);
409	                    match slot {
410	                        Ok(index) => assert_eq!(removed, Some(model.remove(index).1)),
411	                        Err(_) => assert_eq!(removed, None),
412	                    }
413	                } else {
414	                    let value = step;
415	                    let replaced = store.insert(key, value);
416	                    match slot {
417	                        Ok(index) => {
418	                            assert_eq!(replaced, Some(model[index].1));
419	                            model[index].1 = value;
420	                        }
421	                        Err(index) => {
422	                            assert_eq!(replaced, None);
423	                            model.insert(index, (key, value));
424	                        }
425	                    }
426	                }
427	                assert_eq!(store.len(), model.len());
428	            }
429	            assert_invariants(&store);
430	            assert_eq!(collect(&store), model);
431	            for probe in -2..152 {
432	                let expected = model.iter().position(|entry| entry.0 >= probe);
433	                assert_eq!(
434	                    store.at(store.lower_bound(&probe)).map(|(k, _)| *k),
435	                    expected.map(|i| model[i].0)
436	                );
437	                let expected = model.iter().position(|entry| entry.0 > probe);
438	                assert_eq!(
439	                    store.at(store.upper_bound(&probe)).map(|(k, _)| *k),
440	                    expected.map(|i| model[i].0)
441	                );
442	            }
443	        }
444	    }
445	}
