// Independent stress harness for the REAL, unmodified bucket engine.
#[path = "/output/sortedcontainers/buckets.rs"]
mod buckets;

use self::buckets::{Buckets, Pos};

struct Rng(u64);
impl Rng {
    fn new(seed: u64) -> Rng {
        Rng(seed)
    }
    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }
}

struct Stats {
    ops: u64,
    splits: u64,
    bucket_drops: u64,
    merges: u64,
    merge_splits: u64,
    max_buckets: usize,
    max_bucket_len: usize,
}

/// Full structural + behavioural audit, run after every single operation.
///
/// Everything the module keeps private is still observable from outside:
///   * the number of buckets is `end().bucket`;
///   * each element's (bucket, offset) comes from walking `advance` from the front,
///     which yields every bucket's exact length.
/// Returns the bucket-size vector so the caller can classify structural transitions.
fn audit(
    store: &Buckets<i32, i32>,
    model: &[(i32, i32)],
    load: usize,
    deep: bool,
    ctx: &str,
) -> Vec<usize> {
    assert_eq!(store.len(), model.len(), "len desync [{}]", ctx);
    assert_eq!(store.is_empty(), model.is_empty(), "is_empty desync [{}]", ctx);

    let end = store.end();
    assert!(store.at(end).is_none(), "end() dereferenceable [{}]", ctx);
    assert_eq!(store.advance(end), end, "advance(end) moved [{}]", ctx);
    assert_eq!(end.offset, 0, "end() not normalised [{}]", ctx);

    // Out-of-range positions must be inert, never panic.
    let wild = Pos {
        bucket: end.bucket + 7,
        offset: 999,
    };
    assert!(store.at(wild).is_none(), "wild pos readable [{}]", ctx);
    assert_eq!(store.advance(wild), wild, "wild pos advanced [{}]", ctx);

    let mut sizes: Vec<usize> = Vec::new();
    let mut seen = 0usize;
    let mut prev: Option<i32> = None;
    let mut pos = store.lower_bound(&i32::MIN);
    if !model.is_empty() {
        assert_eq!(
            pos,
            Pos {
                bucket: 0,
                offset: 0
            },
            "front pos not (0,0) [{}]",
            ctx
        );
    }
    let mut guard = 0usize;
    while let Some((k, v)) = store.at(pos) {
        // Invariant 1 (no empty buckets) and Pos normalisation: bucket indices must be
        // consecutive starting at 0 and offsets must run 0,1,2,... inside each bucket.
        if pos.bucket == sizes.len() {
            assert_eq!(pos.offset, 0, "bucket {} starts at {} [{}]", pos.bucket, pos.offset, ctx);
            sizes.push(0);
        } else {
            assert_eq!(pos.bucket, sizes.len() - 1, "bucket index jumped [{}]", ctx);
            assert_eq!(pos.offset, sizes[pos.bucket], "offset gap [{}]", ctx);
        }
        sizes[pos.bucket] += 1;

        assert_eq!(*k, model[seen].0, "key mismatch at {} [{}]", seen, ctx);
        assert_eq!(*v, model[seen].1, "value mismatch at {} [{}]", seen, ctx);
        // Invariant 2 (strictly increasing keys, across buckets included).
        if let Some(p) = prev {
            assert!(p < *k, "keys out of order: {} then {} [{}]", p, k, ctx);
        }
        prev = Some(*k);

        if deep {
            // A freshly recomputed position must be bit-identical to the walked one,
            // otherwise two Pos values name the same element and Cursor == breaks.
            assert_eq!(store.find(k), pos, "find(key) != walked pos [{}]", ctx);
            assert_eq!(store.lower_bound(k), pos, "lower_bound(key) != walked pos [{}]", ctx);
            assert_eq!(store.get(k), Some(v), "get disagrees with walk [{}]", ctx);
        }

        seen += 1;
        let next = store.advance(pos);
        assert!(next != pos, "advance stalled [{}]", ctx);
        pos = next;
        guard += 1;
        assert!(guard <= model.len() + 4, "walk did not terminate [{}]", ctx);
    }
    assert_eq!(seen, model.len(), "walk visited {} of {} [{}]", seen, model.len(), ctx);
    assert_eq!(pos, end, "walk terminus {:?} != end {:?} [{}]", pos, end, ctx);
    assert_eq!(sizes.len(), end.bucket, "trailing empty bucket(s) [{}]", ctx);
    for (i, s) in sizes.iter().enumerate() {
        assert!(*s >= 1, "empty bucket {} [{}]", i, ctx);
        assert!(*s <= 2 * load, "bucket {} has {} > 2*load={} [{}]", i, s, 2 * load, ctx);
    }

    // iter() must agree with the model too (independent of the Pos walk).
    let collected: Vec<(i32, i32)> = store.iter().map(|(k, v)| (*k, *v)).collect();
    assert_eq!(collected.len(), model.len(), "iter length [{}]", ctx);
    assert_eq!(&collected[..], model, "iter contents [{}]", ctx);

    sizes
}

fn probe(store: &Buckets<i32, i32>, model: &[(i32, i32)], p: i32, ctx: &str) {
    let lb = store.lower_bound(&p);
    let want = model.iter().position(|e| e.0 >= p);
    assert_eq!(
        store.at(lb).map(|(k, _)| *k),
        want.map(|i| model[i].0),
        "lower_bound({}) [{}]",
        p,
        ctx
    );
    assert_eq!(lb == store.end(), want.is_none(), "lower_bound end-ness [{}]", ctx);

    let ub = store.upper_bound(&p);
    let want = model.iter().position(|e| e.0 > p);
    assert_eq!(
        store.at(ub).map(|(k, _)| *k),
        want.map(|i| model[i].0),
        "upper_bound({}) [{}]",
        p,
        ctx
    );
    assert_eq!(ub == store.end(), want.is_none(), "upper_bound end-ness [{}]", ctx);

    let f = store.find(&p);
    let want = model.iter().position(|e| e.0 == p);
    match want {
        Some(i) => {
            assert!(f != store.end(), "find({}) missed [{}]", p, ctx);
            assert_eq!(store.at(f).map(|(k, v)| (*k, *v)), Some(model[i]), "find val [{}]", ctx);
            // equal_range must span exactly one entry.
            assert_eq!(store.advance(lb), ub, "equal_range width [{}]", ctx);
        }
        None => {
            assert_eq!(f, store.end(), "find({}) hallucinated [{}]", p, ctx);
            assert_eq!(lb, ub, "empty equal_range not degenerate [{}]", ctx);
        }
    }
    assert_eq!(store.get(&p), want.map(|i| &model[i].1), "get({}) [{}]", p, ctx);
}

/// Classify what happened to the bucket layout, to prove the rare paths were reached.
fn classify(before: &[usize], after: &[usize], stats: &mut Stats) {
    stats.max_buckets = stats.max_buckets.max(after.len());
    for s in after {
        stats.max_bucket_len = stats.max_bucket_len.max(*s);
    }
    if after.len() == before.len() + 1 {
        stats.splits += 1;
    } else if after.len() + 1 == before.len() {
        // Either an emptied bucket was dropped or a runt was merged into a neighbour.
        let dropped_total: usize = before.iter().sum();
        let kept_total: usize = after.iter().sum();
        if dropped_total == kept_total + 1 {
            // Which one? A drop leaves every other bucket untouched.
            let mut i = 0;
            while i < after.len() && after[i] == before[i] {
                i += 1;
            }
            // suffix match => a whole bucket vanished (it held exactly 1 element)
            let tail_ok = (i..after.len()).all(|j| after[j] == before[j + 1]);
            if tail_ok && before[i] == 1 {
                stats.bucket_drops += 1;
            } else {
                stats.merges += 1;
            }
        }
    } else if after.len() == before.len() && before.iter().sum::<usize>() == after.iter().sum::<usize>() + 1 {
        // Same bucket count with one fewer element: plain removal, or merge-then-split.
        let diffs = (0..after.len()).filter(|i| after[*i] != before[*i]).count();
        if diffs > 1 {
            stats.merge_splits += 1;
        }
    }
    let _ = stats;
}

fn run_random(load: usize, key_space: i32, ops: u64, seed: u64, stats: &mut Stats) {
    let mut rng = Rng::new(seed);
    let mut store: Buckets<i32, i32> = Buckets::new(load);
    let mut model: Vec<(i32, i32)> = Vec::new();
    let effective = if load == 0 { 1 } else { load };
    let mut sizes = audit(&store, &model, effective, true, "init");

    for step in 0..ops {
        let ctx = format!("load={} space={} seed={} step={}", load, key_space, seed, step);
        let key = (rng.below(key_space as u64) as i32) - key_space / 3;
        let slot = model.binary_search_by(|e| e.0.cmp(&key));
        let deep = step % 4 == 0;
        let before = sizes;
        match rng.below(100) {
            0..=33 => {
                // insert
                let value = (step as i32).wrapping_mul(7).wrapping_add(1);
                let got = store.insert(key, value);
                match slot {
                    Ok(i) => {
                        assert_eq!(got, Some(model[i].1), "insert displaced [{}]", ctx);
                        model[i].1 = value;
                    }
                    Err(i) => {
                        assert_eq!(got, None, "insert reported a phantom [{}]", ctx);
                        model.insert(i, (key, value));
                    }
                }
            }
            34..=63 => {
                // remove
                let got = store.remove(&key);
                match slot {
                    Ok(i) => assert_eq!(got, Some(model.remove(i).1), "remove value [{}]", ctx),
                    Err(_) => assert_eq!(got, None, "remove of absent key [{}]", ctx),
                }
            }
            64..=83 => {
                // get_or_insert_with, then write through the returned reference: this is the
                // only path that hands out a &mut derived from insert_at's translated Pos.
                let fresh = (step as i32).wrapping_mul(13).wrapping_sub(3);
                let written = fresh ^ 0x5A5A;
                {
                    let slot_ref = store.get_or_insert_with(key, || fresh);
                    match slot {
                        Ok(i) => assert_eq!(*slot_ref, model[i].1, "goiw existing value [{}]", ctx),
                        Err(_) => assert_eq!(*slot_ref, fresh, "goiw fresh value [{}]", ctx),
                    }
                    *slot_ref = written;
                }
                match slot {
                    Ok(i) => model[i].1 = written,
                    Err(i) => model.insert(i, (key, written)),
                }
                assert_eq!(store.get(&key), Some(&written), "goiw write lost [{}]", ctx);
            }
            84..=93 => {
                // get_mut, write through
                let got = store.get_mut(&key);
                match slot {
                    Ok(i) => {
                        let r = got.expect("get_mut missed a present key");
                        assert_eq!(*r, model[i].1, "get_mut value [{}]", ctx);
                        *r = model[i].1.wrapping_add(1);
                        model[i].1 = model[i].1.wrapping_add(1);
                    }
                    Err(_) => assert!(got.is_none(), "get_mut on absent key [{}]", ctx),
                }
            }
            94..=98 => {
                // pure lookups
                probe(&store, &model, key, &ctx);
            }
            _ => {
                if rng.below(50) == 0 {
                    store.clear();
                    model.clear();
                }
            }
        }
        stats.ops += 1;
        sizes = audit(&store, &model, effective, deep, &ctx);
        classify(&before, &sizes, stats);

        // A couple of random probes plus the boundary probes every op.
        for _ in 0..2 {
            let p = (rng.below(key_space as u64 + 6) as i32) - key_space / 3 - 3;
            probe(&store, &model, p, &ctx);
        }
        probe(&store, &model, i32::MIN, &ctx);
        probe(&store, &model, i32::MAX, &ctx);
        if let Some(last) = model.last().map(|e| e.0) {
            probe(&store, &model, last, &ctx);
            probe(&store, &model, last + 1, &ctx);
            let first = model[0].0;
            probe(&store, &model, first, &ctx);
            probe(&store, &model, first - 1, &ctx);
        }
    }
}

/// Adversarial deterministic shapes: monotone runs, boundary churn, full drain/refill.
fn run_patterns(load: usize, stats: &mut Stats) {
    let effective = if load == 0 { 1 } else { load };
    let n = 6 * load as i32 + 17;

    // ascending fill, then drain from the front (hammers rebalance on bucket 0)
    {
        let mut store: Buckets<i32, i32> = Buckets::new(load);
        let mut model: Vec<(i32, i32)> = Vec::new();
        let mut sizes = audit(&store, &model, effective, true, "asc init");
        for k in 0..n {
            store.insert(k, k);
            model.push((k, k));
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "asc fill");
            classify(&before, &sizes, stats);
        }
        for k in 0..n {
            store.remove(&k);
            model.remove(0);
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "asc drain front");
            classify(&before, &sizes, stats);
        }
    }
    // descending fill, then drain from the back (rebalance on the last bucket)
    {
        let mut store: Buckets<i32, i32> = Buckets::new(load);
        let mut model: Vec<(i32, i32)> = Vec::new();
        let mut sizes = audit(&store, &model, effective, true, "desc init");
        for k in (0..n).rev() {
            store.insert(k, k);
            model.insert(0, (k, k));
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "desc fill");
            classify(&before, &sizes, stats);
        }
        for k in (0..n).rev() {
            store.remove(&k);
            model.pop();
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "desc drain back");
            classify(&before, &sizes, stats);
        }
    }
    // Fill, then repeatedly empty one interior bucket down to a runt and merge it.
    {
        let mut store: Buckets<i32, i32> = Buckets::new(load);
        let mut model: Vec<(i32, i32)> = Vec::new();
        for k in 0..(20 * load as i32 + 40) {
            store.insert(k * 2, k);
            model.push((k * 2, k));
        }
        let mut sizes = audit(&store, &model, effective, true, "interior init");
        // remove every third key, forward
        let keys: Vec<i32> = model.iter().map(|e| e.0).collect();
        for (i, k) in keys.iter().enumerate() {
            if i % 3 != 1 {
                continue;
            }
            store.remove(k);
            let idx = model.iter().position(|e| e.0 == *k).unwrap();
            model.remove(idx);
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "interior thin");
            classify(&before, &sizes, stats);
            // reinsert a key that lands exactly on a bucket boundary
            store.insert(*k, -1);
            let ins = model.binary_search_by(|e| e.0.cmp(k)).unwrap_err();
            model.insert(ins, (*k, -1));
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "interior refill");
            classify(&before, &sizes, stats);
        }
    }
    // Alternate insert-lowest / remove-lowest forever: keeps bucket 0 at the edge.
    {
        let mut store: Buckets<i32, i32> = Buckets::new(load);
        let mut model: Vec<(i32, i32)> = Vec::new();
        for k in 0..(4 * load as i32 + 9) {
            store.insert(k, k);
            model.push((k, k));
        }
        let mut sizes = audit(&store, &model, effective, true, "edge init");
        for t in 0..200 {
            let k = -1 - t;
            store.insert(k, k);
            model.insert(0, (k, k));
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "edge insert-front");
            classify(&before, &sizes, stats);
            store.remove(&k);
            model.remove(0);
            stats.ops += 1;
            let before = sizes;
            sizes = audit(&store, &model, effective, true, "edge remove-front");
            classify(&before, &sizes, stats);
        }
    }
}

fn main() {
    let mut stats = Stats {
        ops: 0,
        splits: 0,
        bucket_drops: 0,
        merges: 0,
        merge_splits: 0,
        max_buckets: 0,
        max_bucket_len: 0,
