/// Which bucket holds model element `index`, given the bucket-size vector.
fn bucket_of(sizes: &[usize], index: usize) -> usize {
    let mut acc = 0;
    for (i, s) in sizes.iter().enumerate() {
        acc += *s;
        if index < acc {
            return i;
        }
    }
    sizes.len()
}

