#[path = "/output/sortedcontainers/buckets.rs"]
mod buckets;
use self::buckets::{Buckets, Pos};
fn main() {
    // load = 2^63 makes `load * 2` wrap to 0 in release: every bucket splits on every insert.
    let mut b: Buckets<i32, i32> = Buckets::new(1usize << 63);
    let mut model: Vec<i32> = Vec::new();
    let mut st = 12345u64;
    for i in 0..3000 {
        st = st.wrapping_mul(6364136223846793005).wrapping_add(1);
        let k = ((st >> 33) % 500) as i32;
        if i % 3 == 2 { b.remove(&k); model.retain(|x| *x != k); }
        else { if b.insert(k, k).is_none() { model.push(k); model.sort(); } }
        // structural walk
        let mut pos = b.lower_bound(&i32::MIN);
        let mut seen = 0; let mut prev = None; let mut sizes: Vec<usize> = Vec::new();
        while let Some((kk, _)) = b.at(pos) {
            if pos.bucket == sizes.len() { assert_eq!(pos.offset, 0); sizes.push(0); }
            else { assert_eq!(pos.bucket, sizes.len()-1); assert_eq!(pos.offset, sizes[pos.bucket]); }
            sizes[pos.bucket] += 1;
            if let Some(p) = prev { assert!(p < *kk, "order broken"); }
            prev = Some(*kk);
            assert_eq!(b.find(kk), pos, "pos not normalised");
            seen += 1; pos = b.advance(pos);
            assert!(seen <= model.len()+2);
        }
        assert_eq!(seen, model.len(), "empty bucket / walk truncated at i={}", i);
        assert_eq!(pos, b.end());
        assert_eq!(sizes.len(), b.end().bucket, "trailing empty bucket at i={}", i);
        assert!(sizes.iter().all(|s| *s >= 1), "empty bucket at i={}", i);
        assert_eq!(b.len(), model.len());
    }
    let _ = Pos { bucket: 0, offset: 0 };
    println!("wrapped-load run OK: len={} nbuckets={}", b.len(), b.end().bucket);
}
